<?php
require_once __DIR__ . '/../config/config.php'; require_once __DIR__ . '/../includes/functions.php';
if(current_user()) redirect(is_admin()?'admin/dashboard.php':'student/dashboard.php');$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=trim($_POST['full_name']??'');$email=strtolower(trim($_POST['email']??''));$pass=$_POST['password']??'';if($name===''||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($pass)<8){$error='Enter your name, a valid email, and a password of at least 8 characters.';}else{try{$st=$pdo->prepare("INSERT INTO users(full_name,email,password,role) VALUES(?,?,?,'student')");$st->execute([$name,$email,password_hash($pass,PASSWORD_DEFAULT)]);flash('success','Your student account has been created. Please log in.');redirect('auth/login.php');}catch(PDOException $e){error_log($e->getMessage());$error='This email may already be registered.';}}}
page_header('Student registration');?><div class="panel"><h1>Create student account</h1><?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif;?><form class="form" method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><label>Full name</label><input name="full_name" maxlength="150" required><label>Email</label><input type="email" name="email" required><label>Password (minimum 8 characters)</label><input type="password" name="password" minlength="8" required><button>Create account</button></form></div><?php page_footer();?>
